package com.openggf.game.soniccd.player;
import com.openggf.game.soniccd.objects.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Tests FIRST, constructed synchronous ActiveOwner only; no private World/native admission. */
class TestCdPlayerTimeWarpActiveOperations {
 @Test void present210PublishesLockPeriodAll26SavedStoresThenSpawn(){var h=new Host();var r=h.run();assertEquals(0x137,h.lock);assertEquals(0x80,h.period);assertEquals(2,h.spawn);assertEquals(26,h.savedStores.size());assertEquals(List.of(CdTimeWarpSaveData.Store.values()),h.savedStores);assertEquals(1,h.saved.read(CdTimeWarpSaveData.SavedField.SPAWN_MODE));assertEquals(0,h.saved.read(CdTimeWarpSaveData.SavedField.PRIMARY_FLAGS)&0x48);assertEquals(0x50000,h.saved.read(CdTimeWarpSaveData.SavedField.TIME_LONG));assertEquals(h.saved,r.saveResult().orElseThrow().finalSavedState());assertEquals(0,h.restart);assertEquals(List.of("LOCK","PERIOD"),h.writes.subList(0,2));assertEquals("SPAWN",h.writes.getLast());}
 @Test void activeCompletionMatchesTheExistingDetachedSaveValueAndObservations(){var h=new Host();var before=h.saved;var legacy=CdPlayerTimeWarp.step(h.input(),new CdPlayerTimeWarp.Context(OptionalInt.of(h.spawn),Optional.empty(),Optional.of(new CdPlayerTimeWarp.SaveContext(before,new CdPlayerTimeWarp.SaveReads(){public int readScrollLockWord(){return h.lock;}public int read(CdTimeWarpSaveData.Source s){return h.value(s);}}))));assertEquals(legacy,h.run());}
 @Test void legacyOriginalEntryStillStopsAtItsExplicit210Boundary(){var h=new Host();var e=assertThrows(CdPlayerTimeWarp.UnsupportedTimeWarp.class,()->CdPlayerTimeWarp.stepOriginal(h.input(),new CdPlayerTimeWarp.Context(OptionalInt.of(1),Optional.empty()),h));assertEquals(CdPlayerTimeWarp.UnsupportedBoundary.SCROLL_LOCK_WRITE,e.boundary());assertTrue(h.writes.isEmpty());}
 @Test void activeSpawnTwoReturnsBeforeLockOrSavedReads(){var h=new Host();h.spawn=2;h.run();assertEquals(List.of(CdPlayerTimeWarp.OriginalValue.SPAWN_MODE_BYTE),h.scalarReads);assertEquals(0,h.savedReads);assertTrue(h.writes.isEmpty());}
 @Test void refusedLockKeepsOriginalThrowableAndEveryLaterPartition(){var h=new Host();h.faultAt="LOCK";var old=h.saved;assertSame(h.fault,assertThrows(Fault.class,h::run));assertEquals(0x37,h.lock);assertEquals(1,h.period);assertEquals(1,h.spawn);assertSame(old,h.saved);assertEquals(0,h.fault.getSuppressed().length);}
 @Test void landedLockFaultRetainsOnlyTheRealHighByteStore(){var h=new Host();h.faultAt="LOCK";h.landed=true;assertSame(h.fault,assertThrows(Fault.class,h::run));assertEquals(0x137,h.lock);assertEquals(1,h.period);assertEquals(1,h.spawn);assertEquals(0,h.savedStores.size());}
 @Test void sourceFaultRetainsTheExactPriorSavedPrefixAndNoSpawn(){var h=new Host();h.readFault=CdTimeWarpSaveData.Source.PRIMARY_Y;assertSame(h.fault,assertThrows(Fault.class,h::run));assertEquals(List.of(CdTimeWarpSaveData.Store.SAVED_SPAWN,CdTimeWarpSaveData.Store.SAVED_X),h.savedStores);assertEquals(0x1234,h.saved.read(CdTimeWarpSaveData.SavedField.PRIMARY_X));assertThrows(CdTimeWarpSaveData.UnknownSavedByte.class,()->h.saved.read(CdTimeWarpSaveData.SavedField.PRIMARY_Y));assertEquals(1,h.spawn);assertEquals(0x80,h.period);}
 @Test void landedSavedFaultRetainsItsActualStoreAndExpiresTheOccurrence(){var h=new Host();h.faultAt="SAVED_X";h.landed=true;assertSame(h.fault,assertThrows(Fault.class,h::run));assertEquals(0x1234,h.saved.read(CdTimeWarpSaveData.SavedField.PRIMARY_X));assertEquals(1,h.spawn);assertThrows(IllegalStateException.class,()->h.last.requireCurrent(h));assertEquals(0,h.fault.getSuppressed().length);}
 @Test void pastFadePrecedesPeriodAndNoOtherProfileReadIsInvented(){var h=new Host();h.period=0;h.direction=255;h.run();assertEquals(List.of("LOCK","FADEPCM","PERIOD"),h.writes.subList(0,3));assertEquals(0x80,h.period);}
 @Test void rawPeriodSignedUnderflowAndFutureClampUseTheSharedArithmetic(){for(int[] v:new int[][]{{0,255,128},{2,1,130},{255,1,128},{1,255,128}}){var h=new Host();h.period=v[0];h.direction=v[1];h.run();assertEquals(v[2],h.period);}}
 @Test void timer230WritesRestartHighByteThenOneMusicCommandWithoutReadingSpawn(){var h=new Host();h.timer=230;h.restart=0xA5;var r=h.run();assertEquals(0x1A5,h.restart);assertEquals(List.of("RESTART","FADE_MUSIC"),h.writes);assertEquals(List.of(CdPlayerTimeWarp.OriginalValue.LEVEL_RESTART_WORD),h.scalarReads);assertEquals(0,h.savedReads);assertTrue(r.saveResult().isEmpty());assertTrue(r.restartResult().isEmpty(),"Actual native stores are not detached work for Body to replay");}
 @Test void landedRestartFaultPrecedesMusicAndKeepsItsLowByte(){var h=new Host();h.timer=230;h.restart=0xA5;h.faultAt="RESTART";h.landed=true;assertSame(h.fault,assertThrows(Fault.class,h::run));assertEquals(0x1A5,h.restart);assertEquals(List.of("RESTART"),h.writes);}
 @Test void activeReceiptsRejectForeignThreadRetiredAndNonprimitiveUse(){var h=new Host();h.check=true;h.run();assertThrows(IllegalStateException.class,()->h.last.requireCurrent(h));assertEquals(0,h.fault.getSuppressed().length);}
 private static final class Fault extends RuntimeException{}
 private static final class Host implements CdPlayerTimeWarp.ActiveOwner {
  CdTimeWarpSaveData.State saved=CdTimeWarpSaveData.State.unknown();int timer=210,direction=255,period=1,spawn=1,lock=0x37,restart,savedReads;boolean landed,check;String faultAt="";CdTimeWarpSaveData.Source readFault;final Fault fault=new Fault();final List<String>writes=new ArrayList<>();final List<CdTimeWarpSaveData.Store>savedStores=new ArrayList<>();final List<CdPlayerTimeWarp.OriginalValue>scalarReads=new ArrayList<>();CdPlayerTimeWarp.OriginalCall last;
  CdPlayerTimeWarp.Input input(){return new CdPlayerTimeWarp.Input(0,period,0x199c,0,0x600,direction,timer,1);}
  CdPlayerTimeWarp.Result run(){return CdPlayerTimeWarp.stepOriginalActive(input(),new CdPlayerTimeWarp.Context(OptionalInt.empty(),Optional.empty()),this);}
  public void before(CdPlayerTimeWarp.OriginalCall c){c.requireCurrent(this);last=c;if(check){assertThrows(IllegalStateException.class,()->c.requirePrimitive(this));assertThrows(IllegalStateException.class,()->c.requireCurrent(new Host()));var ref=new AtomicReference<Throwable>();var t=new Thread(()->{try{c.requireCurrent(this);}catch(Throwable e){ref.set(e);}});t.start();try{t.join();}catch(InterruptedException e){throw new AssertionError(e);}assertInstanceOf(IllegalStateException.class,ref.get());}}
  public CdReservedObjectBank.Snapshot reserved(CdPlayerTimeWarp.OriginalCall c){throw new AssertionError("No star read on active210/230");}
  public void store(CdPlayerTimeWarp.OriginalCall c){throw new AssertionError("No timer/star store on active210/230");}
  public int scalar(CdPlayerTimeWarp.OriginalCall c){c.requirePrimitive(this);scalarReads.add(c.value());return switch(c.value()){case SPAWN_MODE_BYTE->spawn;case SCROLL_LOCK_WORD->lock;case LEVEL_RESTART_WORD->restart;};}
  public CdTimeWarpSaveData.State saved(CdPlayerTimeWarp.OriginalCall c){c.requirePrimitive(this);savedReads++;return saved;}
  public int source(CdPlayerTimeWarp.OriginalCall c){c.requirePrimitive(this);if(c.source()==readFault)throw fault;return value(c.source());}
  int value(CdTimeWarpSaveData.Source s){return switch(s){case SPAWN_MODE->spawn;case PRIMARY_X->0x1234;case PRIMARY_Y->0x5678;case PRIMARY_GVEL->0x600;case PRIMARY_X_VELOCITY->0x5F0;case PRIMARY_Y_VELOCITY->0xFFE0;case PRIMARY_FLAGS->0x6A;case TIME_LONG->0x50001;case RINGS->23;case LIVES_FLAGS->3;default->s.width()==1?0x11:0x2222;};}
  public void activeStore(CdPlayerTimeWarp.OriginalCall c){c.requirePrimitive(this);String key;Runnable apply;
   if(c.site()==CdPlayerTimeWarp.OriginalSite.RESTART_STORE){var w=c.restart();key="RESTART";apply=()->{assertEquals(restart,w.expectedRestartWord());restart=w.finalRestartWord();};}
   else if(c.site()==CdPlayerTimeWarp.OriginalSite.FADE_OUT_MUSIC){key="FADE_MUSIC";apply=()->{};}
   else{var e=c.saveEffect();if(e instanceof CdPlayerTimeWarp.LockWrite w){key="LOCK";apply=()->{assertEquals(lock,w.expected());lock=w.value();};}else if(e instanceof CdPlayerTimeWarp.PeriodWrite w){key="PERIOD";apply=()->{assertEquals(period,w.expected());period=w.value();};}else if(e instanceof CdPlayerTimeWarp.SpawnWrite w){key="SPAWN";apply=()->{assertEquals(spawn,w.expected());spawn=w.value();};}else if(e instanceof CdPlayerTimeWarp.SavedWrite w){var x=w.call();key=x.store().name();apply=()->{assertSame(saved,x.expectedState());saved=x.finalState();savedStores.add(x.store());};}else{key="FADEPCM";apply=()->{};}}
   if(key.equals(faultAt)&&!landed)throw fault;apply.run();writes.add(key);if(key.equals(faultAt))throw fault;
  }
  public void after(CdPlayerTimeWarp.OriginalCall c){c.requireCurrent(this);}
  public void failed(CdPlayerTimeWarp.OriginalCall c,Throwable first){c.requireCurrent(this);}
 }
}
